class Controller:
    def __init__(self,s):
        self.s=s; self.m=s.model; self.d=s.data
        self.scratch=mujoco.MjData(self.m)
        self.sid=self.m.site('gripper0_right_grip_site').id
        self.qa=np.array([self.m.joint('robot0_joint'+str(i)).qposadr[0] for i in range(1,8)])
        self.va=np.array([self.m.joint('robot0_joint'+str(i)).dofadr[0] for i in range(1,8)])
        self.limits=self.m.jnt_range[[self.m.joint('robot0_joint'+str(i)).id for i in range(1,8)]]
        self.q=self.d.qpos[self.qa].copy(); self.grip=-1
        self.down=np.array([[0.,1.,0.],[1.,0.,0.],[0.,0.,-1.]])
    def pose(self):
        return self.d.site_xpos[self.sid].copy(),self.d.site_xmat[self.sid].reshape(3,3).copy()
    def ik(self,pos,rot,q0=None):
        dd=self.scratch; dd.qpos[:]=self.d.qpos; q=self.q.copy() if q0 is None else q0.copy()
        jp=np.zeros((3,self.m.nv)); jr=np.zeros((3,self.m.nv))
