            ep=np.asarray(pos)-dd.site_xpos[self.sid]
            er=Rotation.from_matrix(rot@dd.site_xmat[self.sid].reshape(3,3).T).as_rotvec()
            err=np.r_[ep,.4*er]
            if np.linalg.norm(ep)<.0001 and np.linalg.norm(er)<.001: break
            mujoco.mj_jacSite(self.m,dd,jp,jr,self.sid)
            J=np.vstack([jp[:,self.va],.4*jr[:,self.va]])
            dq=J.T@np.linalg.solve(J@J.T+np.eye(6)*.00002,err)
            q=np.clip(q+np.clip(dq,-.12,.12),self.limits[:,0]+.001,self.limits[:,1]-.001)
        return q,float(np.linalg.norm(ep)),float(np.linalg.norm(er))
    def step(self,q=None,grip=None,base=None,torso=0,mode=-1):
        if q is not None: self.q=np.array(q).copy()
        if grip is not None: self.grip=grip
        a=np.r_[self.q,self.grip, [0.,0.,0.] if base is None else base,torso,mode]
        return self.s.step(a)
    def hold(self,n=10,grip=None):
        for _ in range(n): self.step(grip=grip)
    def move(self,pos,rot=None,n=None,speed=.012,settle=8,grip=None):
